              {key}
              <Icon as={FiChevronRight} boxSize={4} color="fg.muted" />
            </Menu.TriggerItem>
            <Menu.Content>
              {menuButtons.map((navItem) => (
                <PluginMenuItem {...navItem} key={navItem.name} />
              ))}
            </Menu.Content>
          </Menu.Root>
        ))}
      </Menu.Content>
    </Menu.Root>
  ) : (
    navItems.map((navItem) => <PluginMenuItem {...navItem} key={navItem.name} topLevel={true} />)
  );
};
